from pathlib import Path
from pynwb import NWBHDF5IO
import numpy as np, sys

def shape(x):
    try: return tuple(x.shape)
    except Exception:
        try: return (len(x),)
        except Exception: return None

def describe(name,obj,indent=''):
    print(f'{indent}{name}: {type(obj).__name__}')
    for attr in ('description','comments','unit','rate','starting_time','conversion','offset'):
        if hasattr(obj,attr):
            try:
                v=getattr(obj,attr)
                if v is not None: print(f'{indent}  {attr}={v!r}')
            except Exception as e: print(f'{indent}  {attr}=ERR {e}')
    if hasattr(obj,'data'):
        print(f'{indent}  data shape={shape(obj.data)} dtype={getattr(obj.data,"dtype",None)}')
    if hasattr(obj,'timestamps') and obj.timestamps is not None:
        print(f'{indent}  timestamps shape={shape(obj.timestamps)} dtype={getattr(obj.timestamps,"dtype",None)}')
    if hasattr(obj,'rois'):
        try: print(f'{indent}  rois table={obj.rois.table.name} region_len={len(obj.rois.data)}')
        except Exception as e: print(f'{indent}  rois ERR={e}')

for fn in sys.argv[1:]:
 print('\n'+'='*100+'\nFILE',fn)
 with NWBHDF5IO(fn,'r',load_namespaces=True) as io:
  n=io.read()
  print('identifier',n.identifier,'session_id',n.session_id,'session_start_time',n.session_start_time)
  print('subject',None if n.subject is None else {a:getattr(n.subject,a,None) for a in ('subject_id','species','sex','age','description')})
  print('description',n.session_description)
  print('acquisition keys',list(n.acquisition.keys()))
  for k,v in n.acquisition.items(): describe(k,v,'  ')
  print('processing modules',list(n.processing.keys()))
  for mk,m in n.processing.items():
   print(' MODULE',mk,repr(m.description),'interfaces',list(m.data_interfaces.keys()))
   for k,v in m.data_interfaces.items():
    describe(k,v,'    ')
    if hasattr(v,'time_series'):
     for sk,sv in v.time_series.items(): describe(sk,sv,'      ')
    if hasattr(v,'roi_response_series'):
     for sk,sv in v.roi_response_series.items(): describe(sk,sv,'      ')
    if hasattr(v,'spatial_series'):
     for sk,sv in v.spatial_series.items(): describe(sk,sv,'      ')
  print('interval tables',list(n.intervals.keys()))
  for k,t in n.intervals.items():
   print(' TABLE',k,'rows',len(t),'columns',list(t.colnames),'description',repr(t.description))
   try: print(t.to_dataframe().head(3).to_string())
   except Exception as e: print(' dataframe ERR',e)
  print('trials',None if n.trials is None else (len(n.trials),list(n.trials.colnames)))
  if n.trials is not None:
   print(n.trials.to_dataframe().head(8).to_string())
  print('units',None if n.units is None else (len(n.units),list(n.units.colnames)))
