from pathlib import Path
from pynwb import NWBHDF5IO
import numpy as np
fn=sorted(Path('/app/data').rglob('*.nwb'))[0]
print('FILE',fn)
with NWBHDF5IO(str(fn),'r',load_namespaces=True) as io:
 n=io.read()
 def inspect(path,o):
  if not hasattr(o,'data'): return
  a=np.asarray(o.data[:])
  print('\n',path,'shape',a.shape,'dtype',a.dtype,'rate',getattr(o,'rate',None),'start',getattr(o,'starting_time',None),'unit',getattr(o,'unit',None))
  finite=a[np.isfinite(a)] if np.issubdtype(a.dtype,np.number) else a
  if np.issubdtype(a.dtype,np.number):
   print(' min/max/mean',float(np.min(finite)),float(np.max(finite)),float(np.mean(finite)),'nan',int(np.isnan(a).sum()))
   u,c=np.unique(a,return_counts=True)
   if len(u)<=30: print(' unique/counts',list(zip(u.tolist(),c.tolist())))
   else: print(' quantiles',np.quantile(finite,[0,.01,.1,.5,.9,.99,1]).tolist())
  print(' first20',a[:20].tolist())
  # transitions, event indices, and reset candidates
  if a.ndim==1 and np.issubdtype(a.dtype,np.number):
   nz=np.flatnonzero(a!=0); print(' nonzero n',len(nz),'first idx',nz[:30].tolist())
   ch=np.flatnonzero(np.diff(a)!=0)+1; print(' changes n',len(ch),'first idx',ch[:30].tolist())
   if 'pos' in path.lower():
    reset=np.flatnonzero(np.diff(a)<-200)+1; print(' position resets n',len(reset),'first',reset[:20].tolist(),'values',a[reset[:10]].tolist())
 for k,v in n.acquisition.items(): inspect('acquisition/'+k,v)
 for mk,m in n.processing.items():
  for k,v in m.data_interfaces.items():
   for attr in ('time_series','spatial_series'):
    if hasattr(v,attr):
     for sk,sv in getattr(v,attr).items(): inspect(f'processing/{mk}/{k}/{sk}',sv)
